CREATE MATERIALIZED VIEW spike.daily_mv UUID '66baf545-cdea-4db1-a33e-abf49da60ed4' TO spike.daily (`day` Date, `users` AggregateFunction(uniq, UInt32), `total` AggregateFunction(sum, Float64)) AS SELECT toDate(ts) AS day, uniqState(user_id) AS users, sumState(amount) AS total FROM spike.events GROUP BY day